# Linguística — lote L16 (ponto L11: redação oficial, a partir do Manual de Redação da Presidência, 3ª ed., 2018, lido no PDF do usuário)
Q = []
TAILS=[" Essa seria a leitura predominante entre os manuais de redação oficial.",
 " Trata-se de orientação corrente na prática da redação oficial.",
 " Tal solução decorreria, segundo esse entendimento, da natureza do expediente.",
 " Essa seria a recomendação mais aceita na administração pública."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.95*len(C) and gap > 8: return E+SHORT[i%len(SHORT)]
    return E
def fonte(ref, conh=False):
    return {"tipo":"doutrina","ref":ref,"versao":"3ª ed., 2018" if not conh else "conhecimento do autor","conferida":"pdf_usuario" if not conh else "conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, ref, conh=False):
    ex = {"fonte": fonte(ref, conh)}
    if conh: ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n=[0]
def M(atom, padE, dif, C, E, com, terro, ref, conh=False):
    _n[0]+=1
    r = "convenção geral; Sistema Internacional de Unidades" if conh else "Manual de Redação da Presidência da República, 3ª ed. (2018), "+ref
    P("L11",[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"k{_n[0]:02d}",r, conh)
# ---- atributos (átomo 11)
M(11,"confusao_instituto",2,"O Manual de Redação da Presidência da República (3ª ed.) elenca como atributos da redação oficial a clareza e precisão, a objetividade, a concisão, a coesão e coerência, a impessoalidade, a formalidade e padronização e o uso da norma padrão da língua portuguesa.","O Manual de Redação da Presidência da República (3ª ed.) elenca como atributos da redação oficial a clareza e precisão, a objetividade, a concisão, a expressividade, a impessoalidade, a formalidade e padronização e o uso da norma padrão da língua portuguesa.","Manual, item 3.","troca coesão e coerência por expressividade","item 3")
M(11,"excecao_omitida",3,"Segundo o Manual, a redação oficial não é necessariamente árida nem contrária à evolução da língua; sua finalidade básica, comunicar com objetividade e máxima clareza, é que impõe parâmetros de uso da língua diversos dos da literatura, do texto jornalístico e da correspondência particular.","Segundo o Manual, a redação oficial é árida por natureza e contrária à evolução da língua, e seus parâmetros de uso são os mesmos da literatura, do texto jornalístico e da correspondência particular.","Manual, item 2.","afirma aridez e equipara à literatura","item 2")
M(11,"troca_autoridade",3,"Para o Manual, os atributos da redação oficial decorrem fundamentalmente do art. 37 da Constituição, e a publicidade, a impessoalidade e a eficiência devem nortear a elaboração dos atos e das comunicações oficiais.","Para o Manual, os atributos da redação oficial decorrem fundamentalmente da LC 95/1998, e a publicidade, a impessoalidade e a eficiência são os únicos princípios que devem nortear as comunicações oficiais.","Manual, item 3.","troca a fonte dos atributos","item 3")
M(11,"troca_efeito",3,"Segundo o Manual, o princípio constitucional da publicidade não se esgota na mera publicação do texto, estendendo-se à necessidade de que o texto seja claro.","Segundo o Manual, o princípio constitucional da publicidade se esgota na publicação do texto no Diário Oficial, de modo que a clareza é questão de estilo e não de transparência.","Manual, item 3.1.","restringe publicidade à publicação","item 3.1")
M(11,"excecao_omitida",4,"Para obter clareza, o Manual sugere frases curtas e bem estruturadas, orações na ordem direta e uniformidade do tempo verbal, admitindo a ordem inversa em certas ocasiões para evitar ambiguidade.","Para obter clareza, o Manual sugere frases curtas e bem estruturadas, orações na ordem direta e uniformidade do tempo verbal, vedando a ordem inversa mesmo quando ela evitaria ambiguidade.","Manual, item 3.1.","veda ordem inversa","item 3.1")
M(11,"confusao_instituto",3,"O Manual recomenda que palavras e expressões em outro idioma sejam usadas só quando indispensáveis, por serem de uso consagrado ou não terem exata tradução, e que sejam grafadas em itálico.","O Manual recomenda que palavras e expressões em outro idioma sejam usadas com liberdade, para conferir elegância ao texto, e que sejam grafadas entre aspas.","Manual, itens 3.1 e 10.2.","altera grafia e permissão","itens 3.1 e 10.2")
M(11,"troca_efeito",3,"A precisão complementa a clareza e se caracteriza, entre outros aspectos, por manifestar a ideia com as mesmas palavras, evitando a sinonímia com propósito meramente estilístico, e por evitar expressão que confira duplo sentido ao texto.","A precisão complementa a clareza e se caracteriza, entre outros aspectos, pela variação de sinônimos para evitar repetições, por conferir elegância ao texto, e pela escolha de expressões de sentido amplo.","Manual, item 3.1.","inverte regra de sinonímia","item 3.1")
M(11,"generalizacao",3,"Segundo o Manual, a clareza e a precisão não se atingem por si sós, pois dependem das demais características da redação oficial, e a releitura do texto redigido é indispensável.","Segundo o Manual, a clareza e a precisão se atingem por si sós, sem depender das demais características da redação oficial, e a releitura do texto é dispensável para quem domina o assunto.","Manual, item 3.1.","afirma autonomia e dispensa releitura","item 3.1")
M(11,"restricao_indevida",3,"A objetividade consiste em ir diretamente ao assunto, sem voltas e sem redundâncias, e é errado supor que ela suprima a delicadeza de expressão ou torne o texto rude e grosseiro.","A objetividade consiste em ir diretamente ao assunto, sem voltas e sem redundâncias, e implica suprimir a delicadeza de expressão, o que torna o texto oficial necessariamente seco e rude.","Manual, item 3.2.","liga objetividade a rudeza","item 3.2")
M(11,"excecao_omitida",3,"Conciso é o texto que transmite o máximo de informações com o mínimo de palavras, o que não autoriza eliminar passagens substanciais do texto com o único objetivo de reduzi-lo em tamanho.","Conciso é o texto que transmite o máximo de informações com o mínimo de palavras, o que autoriza eliminar passagens substanciais do texto para reduzi-lo em tamanho.","Manual, item 3.3.","admite cortar conteúdo","item 3.3")
M(11,"caso_concreto",4,"Um redator que, para obter concisão, elimina adjetivos e advérbios inúteis, caracterizações supérfluas e subordinação excessiva, mas mantém os dados essenciais, aplica corretamente o atributo da concisão.","Um redator que, para obter concisão, acrescenta adjetivos intensificadores às ideias principais e emprega subordinação para encadear todas as informações em um só período, aplica corretamente o atributo da concisão.","Manual, item 3.3.","inverte medidas de concisão","item 3.3")
M(11,"confusao_instituto",3,"Entre os mecanismos que estabelecem a coesão e a coerência de um texto, o Manual aponta a referência, a substituição, a elipse e o uso de conjunção.","Entre os mecanismos que estabelecem a coesão e a coerência de um texto, o Manual aponta a referência, a substituição, a hipérbole e o uso de conjunção.","Manual, item 3.4.","troca mecanismo","item 3.4")
M(11,"confusao_instituto",4,"No período 'O decreto regulamenta os casos gerais; a portaria, os particulares', a omissão do verbo 'regulamenta' na segunda oração é exemplo de elipse, termo recuperável pelo contexto.","No período 'O decreto regulamenta os casos gerais; a portaria, os particulares', a omissão do verbo 'regulamenta' na segunda oração é exemplo de substituição, colocação de um item lexical no lugar de outro.","Manual, item 3.4.","confunde elipse e substituição","item 3.4")
M(11,"confusao_instituto",3,"A impessoalidade remete a dois aspectos: a administração pública não deve privilegiar ou prejudicar ninguém, orientando-se pelo interesse público, e há abstração da pessoalidade dos atos administrativos, pois a ação do servidor resulta da vontade estatal.","A impessoalidade remete a um único aspecto: a proibição da primeira pessoa e da voz ativa nos textos, o que torna a vontade do servidor irrelevante para a comunicação oficial.","Manual, item 3.5.","reduz impessoalidade a regra de voz","item 3.5")
M(11,"excecao_omitida",3,"Segundo o Manual, o tratamento impessoal das comunicações oficiais decorre da ausência de impressões individuais de quem comunica, da impessoalidade de quem recebe a comunicação e do caráter impessoal do próprio assunto tratado.","Segundo o Manual, o tratamento impessoal das comunicações oficiais decorre da ausência de impressões individuais de quem comunica e da identificação nominal do destinatário, que deve ser tratado de forma personalizada.","Manual, item 3.5.","omite fundamento e personaliza destinatário","item 3.5")
M(11,"caso_concreto",3,"Um expediente assinado por chefe de seção é comunicação feita em nome do serviço público e, por isso, não comporta as impressões individuais do signatário.","Um expediente assinado por chefe de seção pode registrar as impressões individuais do signatário, pois quem assina assume a autoria da comunicação em nome próprio.","Manual, item 3.5.","atribui autoria pessoal ao signatário","item 3.5")
M(11,"restricao_indevida",2,"A formalidade e a padronização aplicam-se às comunicações feitas em meio eletrônico, como o e-mail e o documento gerado no SEI, e aos eventuais documentos impressos.","A formalidade e a padronização aplicam-se aos documentos impressos, e as comunicações feitas em meio eletrônico, como o e-mail e o documento gerado no SEI, dispensam as regras de forma.","Manual, item 3.6.","exclui meio eletrônico","item 3.6")
M(11,"restricao_indevida",3,"A formalidade de tratamento não se reduz ao correto emprego do pronome de tratamento para cada autoridade: diz respeito também à civilidade no enfoque dado ao assunto e à uniformidade das comunicações, já que a administração pública federal é una.","A formalidade de tratamento reduz-se ao correto emprego do pronome de tratamento para cada autoridade, e a uniformidade das comunicações é matéria de cada órgão, já que cada um tem sua própria prática.","Manual, item 3.6.","reduz formalidade a pronomes","item 3.6")
M(11,"confusao_instituto",3,"Segundo o Manual, não existe propriamente um padrão oficial de linguagem; o que há é o uso da norma padrão nos atos e nas comunicações oficiais.","Segundo o Manual, existe um padrão oficial de linguagem, a linguagem burocrática, que deve ser adotado nos atos e nas comunicações oficiais para garantir a padronização.","Manual, item 3.6.","afirma padrão burocrático","item 3.6")
M(11,"excecao_omitida",3,"De acordo com o Manual, a língua culta é contra a pobreza de expressão, e não contra a sua simplicidade, e o uso do padrão culto não significa empregar a língua de modo rebuscado nem utilizar figuras de linguagem próprias do estilo literário.","De acordo com o Manual, a língua culta é contra a simplicidade de expressão, e o uso do padrão culto significa empregar a língua de modo rebuscado e utilizar figuras de linguagem próprias do estilo literário.","Manual, item 3.6.","inverte recomendações do padrão culto","item 3.6")
M(11,"troca_efeito",3,"O padrão culto é imprescindível na redação oficial por estar acima das diferenças lexicais, morfológicas ou sintáticas regionais, dos modismos vocabulares e das particularidades linguísticas.","O padrão culto é desejável na redação oficial, mas pode ser substituído pela variedade regional quando o destinatário a utilizar, já que a comunicação eficaz prevalece sobre as diferenças lexicais.","Manual, item 3.6.","admite variedade regional","item 3.6")
M(11,"excecao_omitida",2,"O jargão burocrático, como todo jargão, deve ser evitado, pois terá sempre sua compreensão limitada.","O jargão burocrático é recomendado na redação oficial, pois reforça a padronização e tem compreensão ampla entre os servidores e os cidadãos.","Manual, item 3.6.","recomenda jargão","item 3.6")
M(11,"confusao_instituto",3,"Na redação oficial, quem comunica é sempre o serviço público, o que se comunica é assunto relativo às atribuições do órgão que comunica e o destinatário pode ser o público, uma instituição privada ou outro órgão ou entidade pública.","Na redação oficial, quem comunica é o servidor que assina o expediente, o que se comunica pode ser assunto de sua iniciativa e o destinatário é o público em geral, não se incluindo outros órgãos públicos.","Manual, item 1.","personaliza emissor e restringe destinatário","item 1")
M(11,"troca_efeito",3,"Para a clareza, o Manual sugere não utilizar regionalismos e neologismos e explicitar o significado da sigla na primeira referência a ela.","Para a clareza, o Manual admite regionalismos e neologismos de uso corrente na região do destinatário e dispensa a explicitação da sigla quando ela for conhecida.","Manual, item 3.1.","admite regionalismos","item 3.1")
# ---- pronomes de tratamento, vocativo, endereçamento (átomo 14)
M(14,"confusao_instituto",2,"Os pronomes de tratamento, embora se refiram à segunda pessoa gramatical, levam a concordância para a terceira pessoa.","Os pronomes de tratamento, por se referirem à segunda pessoa gramatical, levam a concordância verbal para a segunda pessoa do plural.","Manual, item 4.1.1.","troca a pessoa da concordância","item 4.1.1")
M(14,"norma_culta",3,"Segundo o Manual, a frase correta é 'Vossa Senhoria designará seu substituto', pois os pronomes possessivos referidos a pronomes de tratamento são os da terceira pessoa.","Segundo o Manual, a frase correta é 'Vossa Senhoria designará vosso substituto', pois os pronomes possessivos referidos a pronomes de tratamento acompanham a segunda pessoa.","Manual, item 4.1.1.","usa possessivo de 2ª pessoa","item 4.1.1")
M(14,"norma_culta",3,"Em ofício dirigido a uma ministra, escreve-se 'Vossa Excelência está atarefada', pois o gênero do adjetivo deve coincidir com o sexo da pessoa a que se refere, e não com o substantivo da locução.","Em ofício dirigido a uma ministra, escreve-se 'Vossa Excelência está atarefado', pois o gênero do adjetivo deve concordar com o substantivo 'Excelência'.","Manual, item 4.1.1.","concorda com o substantivo da locução","item 4.1.1")
M(14,"confusao_instituto",3,"Vossa Excelência e Vossa Senhoria são empregados para comunicar-se diretamente com o receptor, ao passo que Sua Excelência é empregado para fazer referência indireta a alguma autoridade, como no endereçamento do expediente.","Vossa Excelência e Vossa Senhoria são empregados para fazer referência indireta à autoridade, ao passo que Sua Excelência é empregado para comunicar-se diretamente com o receptor do expediente.","Manual, itens 4.1 e 4.1.1.","inverte Vossa e Sua","itens 4.1 e 4.1.1")
M(14,"troca_autoridade",3,"No endereçamento de ofício a autoridade tratada por Vossa Excelência, usa-se a forma 'A Sua Excelência o Senhor' ou 'A Sua Excelência a Senhora'.","No endereçamento de ofício a autoridade tratada por Vossa Excelência, usa-se a forma 'A Vossa Excelência o Senhor' ou 'A Vossa Excelência a Senhora'.","Manual, item 5.1.4.","troca Sua por Vossa","item 5.1.4")
M(14,"troca_autoridade",3,"Quando o tratamento destinado ao receptor for Vossa Senhoria, o endereçamento é 'Ao Senhor' ou 'À Senhora', e não se utiliza a expressão 'A Sua Senhoria o Senhor'.","Quando o tratamento destinado ao receptor for Vossa Senhoria, o endereçamento é 'A Sua Senhoria o Senhor' ou 'A Sua Senhoria a Senhora', e não se utiliza a expressão 'Ao Senhor'.","Manual, item 5.1.4.","inverte forma do endereçamento","item 5.1.4")
M(14,"troca_autoridade",3,"Nas comunicações dirigidas aos Chefes de Poder, o vocativo é composto de 'Excelentíssimo Senhor' ou 'Excelentíssima Senhora' e do cargo respectivo, seguidos de vírgula.","Nas comunicações dirigidas aos Chefes de Poder, o vocativo é composto de 'Ilustríssimo Senhor' ou 'Ilustríssima Senhora' e do cargo respectivo, seguidos de vírgula.","Manual, item 4.4.","troca Excelentíssimo por Ilustríssimo","item 4.4")
M(14,"regra_como_excecao",3,"As demais autoridades, mesmo as tratadas por Vossa Excelência, recebem o vocativo 'Senhor' ou 'Senhora' seguido do cargo respectivo, como em 'Senhora Senadora,'.","As demais autoridades tratadas por Vossa Excelência recebem o mesmo vocativo dos Chefes de Poder, como em 'Excelentíssima Senhora Senadora,'.","Manual, item 4.4.","estende vocativo de Chefe de Poder","item 4.4")
M(14,"caso_concreto",4,"Ao redigir ofício a um deputado federal, o endereçamento é 'A Sua Excelência o Senhor', o vocativo é 'Senhor Deputado,' e, no corpo do texto, o tratamento é Vossa Excelência.","Ao redigir ofício a um deputado federal, o endereçamento é 'Ao Senhor', o vocativo é 'Excelentíssimo Senhor Deputado,' e, no corpo do texto, o tratamento é Vossa Senhoria.","Manual, itens 4.1 e 4.4.","troca endereçamento, vocativo e tratamento","itens 4.1 e 4.4")
M(14,"excecao_omitida",2,"Nas comunicações oficiais, o vocativo é sempre seguido de vírgula.","Nas comunicações oficiais, o vocativo é seguido de dois-pontos quando dirigido a autoridades e de vírgula quando dirigido a particulares.","Manual, item 4.4.","altera pontuação do vocativo","item 4.4")
M(14,"excecao_omitida",3,"Em comunicações oficiais está abolido o uso de Digníssimo (DD) e de Ilustríssimo (Ilmo.), e deve-se evitar o uso indiscriminado de 'doutor', pois o tratamento por meio de Senhor confere a formalidade desejada.","Em comunicações oficiais, o uso de Digníssimo (DD) e de Ilustríssimo (Ilmo.) é recomendado para autoridades tratadas por Vossa Senhoria, e o tratamento 'doutor' deve ser dado a todo bacharel.","Manual, item 4.4.","mantém tratamentos abolidos","item 4.4")
M(14,"excecao_omitida",3,"Na comunicação com particular, o vocativo pode ser 'Senhor' ou 'Senhora' seguido da forma usada pela instituição para referir-se ao interlocutor (como 'Senhor Contribuinte,'), do nome do particular, ou ainda 'Prezado Senhor' e 'Prezada Senhora'.","Na comunicação com particular, o vocativo deve ser sempre 'Excelentíssimo Senhor' ou 'Excelentíssima Senhora', sendo vedado o uso de 'Prezado Senhor' ou da forma usada pela instituição, como 'Senhor Contribuinte'.","Manual, item 4.4.","veda vocativos admitidos","item 4.4")
M(14,"confusao_instituto",3,"No quadro do Manual, a abreviatura V. Exa. é indicada para ministros de Estado, senadores e deputados federais, e consta 'não se usa' abreviatura para o Presidente da República, o Presidente do Congresso Nacional e o Presidente do STF.","No quadro do Manual, a abreviatura V. Exa. é indicada para o Presidente da República, o Presidente do Congresso Nacional e o Presidente do STF, e consta 'não se usa' abreviatura para ministros de Estado, senadores e deputados federais.","Manual, item 4.1.","inverte uso da abreviatura","item 4.1")
M(14,"troca_autoridade",3,"Aos oficiais-generais das Forças Armadas aplica-se Vossa Excelência (vocativo 'Senhor' mais o posto), ao passo que aos outros postos militares aplica-se Vossa Senhoria (V. Sa.).","Aos oficiais-generais das Forças Armadas aplica-se Vossa Senhoria (V. Sa.), ao passo que aos outros postos militares aplica-se Vossa Excelência (vocativo 'Senhor' mais o posto).","Manual, item 4.1.","inverte tratamento militar","item 4.1")
M(14,"confusao_instituto",3,"Na identificação do signatário, 'interino' é aquele nomeado para ocupar transitoriamente cargo público durante a vacância, e 'substituto' é aquele designado para exercer as atribuições de cargo vago ou em caso de afastamento e impedimentos do titular.","Na identificação do signatário, 'substituto' é aquele nomeado para ocupar transitoriamente cargo público durante a vacância, e 'interino' é aquele designado para exercer as atribuições do cargo em caso de afastamento e impedimentos do titular.","Manual, item 4.2.1.","inverte interino e substituto","item 4.2.1")
M(14,"norma_culta",3,"Os termos 'interino' e 'substituto' devem ser utilizados depois do nome do cargo, sem hífen, sem vírgula e em minúsculo, como em 'Secretário-Executivo substituto'.","Os termos 'interino' e 'substituto' devem ser utilizados depois do nome do cargo, com hífen e iniciais maiúsculas, como em 'Secretário-Executivo-Substituto'.","Manual, item 4.2.1.","altera grafia de interino/substituto","item 4.2.1")
M(14,"excecao_omitida",2,"Na identificação do signatário, o cargo ocupado por pessoa do sexo feminino deve ser flexionado no gênero feminino, como em 'Ministra de Estado' e 'Secretária-Executiva interina'.","Na identificação do signatário, o cargo ocupado por pessoa do sexo feminino é mantido na forma masculina, por designar função pública, como em 'Ministro de Estado' e 'Secretário-Executivo interino'.","Manual, item 4.2.2.","mantém masculino","item 4.2.2")
M(14,"norma_culta",4,"Escrevem-se com hífen os cargos formados pelo adjetivo 'geral' (diretor-geral) e pelos prefixos 'ex' e 'vice', mas ficam sem hífen os nomes compostos com elemento de ligação preposicionado, como 'general de exército' e 'capitão de mar e guerra'.","Escrevem-se com hífen os cargos formados pelo adjetivo 'geral' (diretor-geral) e pelos prefixos 'ex' e 'vice', e também os nomes compostos com elemento de ligação preposicionado, como 'general-de-exército' e 'capitão-de-mar-e-guerra'.","Manual, item 4.3.","hifeniza cargos com preposição","item 4.3")
M(14,"norma_culta",4,"Em palavras com hífen, depois de optar pela maiúscula ou pela minúscula, deve-se manter a escolha para todos os elementos: pode-se escrever 'Vice-Presidente' ou 'vice-presidente', mas não 'Vice-presidente'.","Em palavras com hífen, a escolha entre maiúscula e minúscula pode variar entre os elementos, de modo que se admite a grafia 'Vice-presidente', desde que o cargo seja de Chefe de Poder.","Manual, item 4.3.","admite grafia mista","item 4.3")
# ---- padrão ofício (átomo 15)
M(15,"confusao_instituto",2,"Na 3ª edição do Manual, ficou abolida a distinção entre aviso, ofício e memorando, adotando-se o 'padrão ofício', com nomenclatura e diagramação únicas, e o termo ofício passou a ser utilizado nas três hipóteses.","Na 3ª edição do Manual, manteve-se a distinção entre aviso, ofício e memorando, que seguem o padrão ofício, mas diferem pelo destinatário e pela nomenclatura de cada expediente.","Manual, item 5.","mantém distinção abolida","item 5")
M(15,"confusao_instituto",3,"Até a 2ª edição do Manual, o aviso era expedido exclusivamente por Ministros de Estado para autoridades de mesma hierarquia, o ofício era expedido para e pelas demais autoridades, e o memorando era expedido entre unidades administrativas de um mesmo órgão.","Até a 2ª edição do Manual, o ofício era expedido exclusivamente por Ministros de Estado para autoridades de mesma hierarquia, o aviso era expedido para e pelas demais autoridades, e o memorando era expedido entre órgãos distintos.","Manual, item 5.","embaralha antigos expedientes","item 5")
M(15,"confusao_instituto",3,"No ofício circular, um órgão envia o mesmo expediente a mais de um órgão receptor, e a sigla na epígrafe é apenas a do órgão remetente.","No ofício circular, um órgão envia o mesmo expediente a mais de um órgão receptor, e a epígrafe traz as siglas de todos os órgãos receptores.","Manual, item 6.1.","troca siglas da epígrafe","item 6.1")
M(15,"confusao_instituto",3,"No ofício conjunto, mais de um órgão envia, em conjunto, o mesmo expediente a um único órgão receptor, e as siglas dos órgãos remetentes constam da epígrafe.","No ofício conjunto, um único órgão envia o mesmo expediente a mais de um órgão receptor, e as siglas dos órgãos receptores constam da epígrafe.","Manual, item 6.1.","troca remetente e receptor","item 6.1")
M(15,"troca_efeito",3,"A identificação do expediente traz o nome do documento por extenso e em maiúsculas, a abreviatura 'Nº', o número, o ano com quatro dígitos e as siglas do setor da menor para a maior hierarquia, separados por barra, alinhada à margem esquerda.","A identificação do expediente traz o nome do documento por extenso e em maiúsculas, a abreviatura 'Nº', o número, o ano com dois dígitos e as siglas do setor da maior para a menor hierarquia, separados por hífen, alinhada à margem direita.","Manual, item 5.1.2.","altera ordem, ano e alinhamento","item 5.1.2")
M(15,"caso_concreto",4,"Um ofício expedido em Brasília no primeiro dia de outubro de 2026 traz a data 'Brasília, 1º de outubro de 2026.', alinhada à margem direita.","Um ofício expedido em Brasília no primeiro dia de outubro de 2026 traz a data 'Brasília/DF, 01 de Outubro de 2026', alinhada à margem esquerda.","Manual, item 5.1.3.","altera grafia da data","item 5.1.3")
M(15,"troca_efeito",3,"Na grafia da data do ofício, o dia do mês é em numeração ordinal só para o primeiro dia e cardinal para os demais, sem zero à esquerda; o nome do mês é escrito com inicial minúscula; e coloca-se ponto-final depois da data.","Na grafia da data do ofício, o dia do mês é em numeração ordinal para os nove primeiros dias e cardinal para os demais, com zero à esquerda; o nome do mês é escrito com inicial maiúscula; e não se coloca ponto-final depois da data.","Manual, item 5.1.3.","altera regras de grafia da data","item 5.1.3")
M(15,"troca_efeito",3,"O assunto do ofício é precedido da palavra 'Assunto' e de dois-pontos, descrito em frase com inicial maiúscula e sem verbos (sugerindo-se quatro a cinco palavras), destacado em negrito e encerrado com ponto-final.","O assunto do ofício é precedido da palavra 'ASSUNTO' e de travessão, descrito em frase com verbo no infinitivo e inicial minúscula, sem negrito e sem ponto-final.","Manual, item 5.1.5.","altera formato do assunto","item 5.1.5")
M(15,"excecao_omitida",3,"Na introdução do texto do ofício, o Manual recomenda evitar 'Tenho a honra de', 'Tenho o prazer de' e 'Cumpre-me informar que', preferindo a forma direta, como 'Informo', 'Solicito' e 'Comunico'.","Na introdução do texto do ofício, o Manual recomenda empregar 'Tenho a honra de', 'Tenho o prazer de' e 'Cumpre-me informar que', como fórmulas de cortesia que preservam a formalidade e evitam a forma direta.","Manual, item 5.1.6.","recomenda fórmulas evitadas","item 5.1.6")
M(15,"excecao_omitida",4,"Quando o ofício serve para encaminhar documentos, a introdução inicia com referência ao expediente que solicitou o encaminhamento ou, se a remessa não foi solicitada, com a informação do motivo da comunicação, e só há parágrafos de desenvolvimento se o autor quiser comentar o documento.","Quando o ofício serve para encaminhar documentos, a estrutura é a mesma dos demais ofícios, com introdução, desenvolvimento e conclusão obrigatórios, e a referência ao expediente que solicitou o encaminhamento consta da conclusão.","Manual, item 5.1.6.","aplica estrutura geral ao encaminhamento","item 5.1.6")
M(15,"troca_numero",3,"No padrão ofício, os parágrafos são numerados apenas quando o documento tiver três ou mais parágrafos, desde o primeiro, e não se numeram o vocativo e o fecho.","No padrão ofício, os parágrafos são numerados quando o documento tiver mais de um parágrafo, a partir do segundo, e se numeram também o vocativo e o fecho.","Manual, item 5.1.6.","altera regra de numeração","item 5.1.6")
M(15,"troca_numero",3,"O texto do ofício é justificado, com entrelinhas simples, recuo de parágrafo de 2,5 cm, espaçamento de 6 pontos após cada parágrafo e fonte Calibri ou Carlito em corpo 12.","O texto do ofício é alinhado à esquerda, com entrelinhas de 1,5, recuo de parágrafo de 1,25 cm, espaçamento de 12 pontos após cada parágrafo e fonte Times New Roman em corpo 14.","Manual, item 5.1.6.","altera formatação","item 5.1.6")
M(15,"troca_numero",3,"Os documentos do padrão ofício usam papel A4, margem lateral esquerda de no mínimo 3 cm, margem direita de 1,5 cm e margens superior e inferior de 2 cm.","Os documentos do padrão ofício usam papel A4, margem lateral esquerda de 1,5 cm, margem direita de no mínimo 3 cm e margens superior e inferior de 3 cm.","Manual, item 5.2.","troca margens","item 5.2")
M(15,"excecao_omitida",3,"Para destaques, o Manual manda utilizar o negrito, sem abuso, e evitar itálico, sublinhado, maiúsculas, sombreado e outras formatações que afetem a sobriedade e a padronização, reservando o itálico às palavras estrangeiras.","Para destaques, o Manual manda utilizar o sublinhado e o itálico, sem abuso, e evitar o negrito, por afetar a sobriedade do documento, reservando o itálico a todas as palavras estrangeiras.","Manual, item 5.2.","inverte recursos de destaque","item 5.2")
M(15,"confusao_instituto",2,"O Manual estabelece apenas dois fechos para todas as comunicações oficiais: 'Respeitosamente,' para autoridades de hierarquia superior à do remetente, inclusive o Presidente da República, e 'Atenciosamente,' para autoridades de mesma hierarquia, de hierarquia inferior ou nos demais casos.","O Manual estabelece apenas dois fechos para todas as comunicações oficiais: 'Atenciosamente,' para autoridades de hierarquia superior à do remetente, inclusive o Presidente da República, e 'Respeitosamente,' para autoridades de mesma hierarquia, de hierarquia inferior ou nos demais casos.","Manual, item 5.1.7.","inverte fechos","item 5.1.7")
M(15,"caso_concreto",3,"Um coordenador-geral que envia ofício ao Presidente da República encerra o texto com 'Respeitosamente,', pois esse fecho se aplica às autoridades de hierarquia superior, inclusive ao Presidente.","Um coordenador-geral que envia ofício ao Presidente da República encerra o texto com 'Atenciosamente,', pois o Presidente da República é excluído do fecho destinado às autoridades de hierarquia superior.","Manual, item 5.1.7.","exclui o Presidente","item 5.1.7")
M(15,"excecao_omitida",3,"Ficam excluídas dos dois fechos padronizados as comunicações dirigidas a autoridades estrangeiras, que atendem a rito e tradição próprios.","Os dois fechos padronizados aplicam-se também às comunicações dirigidas a autoridades estrangeiras, em respeito à uniformidade das comunicações oficiais.","Manual, item 5.1.7.","aplica fechos a estrangeiros","item 5.1.7")
M(15,"troca_efeito",3,"O fecho da comunicação é alinhado à margem esquerda, com recuo de 2,5 cm, e não é numerado.","O fecho da comunicação é centralizado, sem recuo, e é numerado em sequência aos parágrafos do texto.","Manual, item 5.1.7.","altera formato do fecho","item 5.1.7")
M(15,"troca_efeito",3,"Na identificação do signatário, o nome é grafado em letras maiúsculas, sem negrito e sem linha acima, o cargo traz apenas iniciais maiúsculas, e o bloco é centralizado na página; o Presidente da República, porém, não identifica o signatário.","Na identificação do signatário, o nome é grafado em negrito e com linha acima, o cargo é grafado em maiúsculas, e o bloco é alinhado à direita; o Presidente da República identifica o signatário como as demais autoridades.","Manual, item 5.1.8.","altera identificação do signatário","item 5.1.8")
M(15,"troca_efeito",3,"A numeração das páginas do ofício é obrigatória apenas a partir da segunda página, é centralizada e fica no rodapé.","A numeração das páginas do ofício é obrigatória desde a primeira página, é alinhada à direita e fica no cabeçalho.","Manual, item 5.1.9.","altera numeração de páginas","item 5.1.9")
M(15,"excecao_omitida",3,"O cabeçalho do ofício é utilizado apenas na primeira página e traz o brasão de Armas da República no topo; o uso de marca da instituição deve ser evitado para não se sobrepor ao Brasão.","O cabeçalho do ofício repete-se em todas as páginas e traz a marca da instituição no topo, em lugar do brasão de Armas da República, para valorizar a identidade do órgão.","Manual, item 5.1.1.","altera cabeçalho","item 5.1.1")
# ---- EM, mensagem, e-mail (átomo 16)
M(16,"confusao_instituto",2,"A exposição de motivos é o expediente dirigido ao Presidente ou ao Vice-Presidente da República para propor alguma medida, submeter projeto de ato normativo à sua consideração ou informá-lo de determinado assunto.","A exposição de motivos é o expediente dirigido pelo Presidente da República ao Congresso Nacional para propor alguma medida, submeter projeto de ato normativo ou informar sobre determinado assunto.","Manual, item 6.2.1.","inverte remetente e destinatário","item 6.2.1")
M(16,"excecao_omitida",3,"A exposição de motivos é dirigida ao Presidente da República por um Ministro de Estado e, se o assunto envolver mais de um ministério, é assinada por todos os ministros envolvidos, sendo chamada de interministerial.","A exposição de motivos é dirigida ao Presidente da República por qualquer autoridade do Executivo e, se o assunto envolver mais de um ministério, é assinada pelo Ministro da Casa Civil, sendo chamada de interministerial.","Manual, item 6.2.1.","amplia remetentes e altera signatário","item 6.2.1")
M(16,"troca_numero",3,"A sequência numérica das exposições de motivos é única, seja a EM de um só autor ou interministerial, e a numeração começa e termina dentro de um mesmo ano civil.","A sequência numérica das exposições de motivos interministeriais é própria, separada da das EM de um só autor, e a numeração é contínua, atravessando os anos.","Manual, item 6.2.1.","separa séries e perpetua numeração","item 6.2.1")
M(16,"troca_efeito",3,"Na exposição de motivos, a introdução aponta o problema que demanda a medida ou o ato normativo proposto, o desenvolvimento indica a razão de a medida ser a ideal e as alternativas existentes, e a conclusão propõe novamente a medida a ser tomada.","Na exposição de motivos, a introdução propõe a medida ou o ato normativo, o desenvolvimento aponta o problema que a demanda, e a conclusão indica as alternativas existentes para equacioná-lo.","Manual, item 6.2.2.","troca partes da EM","item 6.2.2")
M(16,"excecao_omitida",3,"As exposições de motivos que encaminham proposições normativas seguem o Decreto nº 9.191/2017 e devem ser instruídas com parecer jurídico e parecer de mérito que permitam a adequada avaliação da proposta.","As exposições de motivos que encaminham proposições normativas dispensam parecer jurídico e de mérito, pois o Decreto nº 9.191/2017 exige parecer apenas para decretos regulamentares.","Manual, item 6.2.2.","dispensa pareceres","item 6.2.2")
M(16,"confusao_instituto",3,"A mensagem é o instrumento de comunicação oficial entre os Chefes dos Poderes Públicos, notadamente as enviadas pelo Chefe do Poder Executivo ao Poder Legislativo para informar sobre fato da administração, expor o plano de governo na abertura da sessão legislativa, submeter matérias que dependem de deliberação e apresentar veto.","A mensagem é o instrumento de comunicação oficial entre unidades administrativas de um mesmo órgão, notadamente as enviadas pelos Ministros de Estado ao Presidente da República para propor medidas e submeter minutas de atos normativos.","Manual, item 6.3.1.","atribui função de memorando/EM","item 6.3.1")
M(16,"troca_autoridade",3,"A mensagem que comunica o veto é dirigida ao Presidente do Senado Federal (art. 66, § 1º, da CF) e seu texto é publicado na íntegra no Diário Oficial da União, ao contrário das demais mensagens, cuja publicação se restringe à notícia do envio ao Legislativo.","A mensagem que comunica o veto é dirigida ao Presidente da Câmara dos Deputados e seu texto é publicado na íntegra no Diário Oficial da União, como o das demais mensagens do Executivo ao Legislativo.","Manual, item 6.3.1, i.","troca destinatário e generaliza publicação","item 6.3.1")
M(16,"troca_autoridade",4,"As mensagens que encaminham projeto de lei ordinária ou complementar seguem com ofício do Ministro Chefe da Casa Civil ao Primeiro-Secretário da Câmara dos Deputados, ao passo que as de PPA, LDO, LOA e créditos adicionais e a de medida provisória seguem com ofício ao Primeiro-Secretário do Senado Federal.","As mensagens que encaminham projeto de lei ordinária ou complementar seguem com ofício do Ministro Chefe da Casa Civil ao Primeiro-Secretário do Senado Federal, ao passo que as de PPA, LDO, LOA e créditos adicionais e a de medida provisória seguem com ofício ao Primeiro-Secretário da Câmara dos Deputados.","Manual, item 6.3.1.","inverte Casas destinatárias","item 6.3.1")
M(16,"excecao_omitida",3,"A mensagem, como os demais atos assinados pelo Presidente da República, não traz identificação de seu signatário, e contém identificação 'MENSAGEM Nº', vocativo, texto e local e data.","A mensagem traz identificação do signatário, com nome e cargo do Presidente da República centralizados abaixo do local e da data, como os demais expedientes do padrão ofício.","Manual, item 6.3.2.","exige signatário","item 6.3.2")
M(16,"troca_autoridade",3,"A mensagem de abertura da sessão legislativa contém o plano de governo, a exposição sobre a situação do País e a solicitação de providências, tem como portador o Chefe da Casa Civil e difere das demais por ser encadernada e distribuída aos congressistas em forma de livro.","A mensagem de abertura da sessão legislativa contém o plano de governo e a prestação de contas do exercício anterior, tem como portador o Presidente do Senado Federal e é distribuída aos congressistas em avulso, como as demais.","Manual, item 6.3.1, g.","troca portador e conteúdo","item 6.3.1")
M(16,"troca_numero",3,"O Presidente da República tem o prazo de 60 dias após a abertura da sessão legislativa para enviar ao Congresso Nacional as contas referentes ao exercício anterior, sob pena de a Câmara dos Deputados realizar a tomada de contas.","O Presidente da República tem o prazo de 90 dias após a abertura da sessão legislativa para enviar ao Congresso Nacional as contas referentes ao exercício anterior, sob pena de o Senado Federal realizar a tomada de contas.","Manual, item 6.3.1, f.","troca prazo e Casa","item 6.3.1")
M(16,"excecao_omitida",3,"Para ausentar-se do país por mais de 15 dias, o Presidente ou o Vice-Presidente da República depende de autorização do Congresso Nacional, e, por cortesia, quando a ausência é inferior a 15 dias, o Presidente comunica a cada Casa por mensagens idênticas.","Para ausentar-se do país por qualquer prazo, o Presidente ou o Vice-Presidente da República depende de autorização do Congresso Nacional, solicitada por mensagem idêntica a cada Casa.","Manual, item 6.3.1, d.","exige autorização em qualquer prazo","item 6.3.1")
M(16,"excecao_omitida",3,"Para que o e-mail tenha valor documental, isto é, possa ser aceito como documento original, é necessária certificação digital ICP-Brasil que ateste a identidade do remetente; o destinatário pode reconhecer como válido o e-mail sem certificação, mas, havendo questionamento, será obrigatória a repetição do ato por documento físico assinado ou meio eletrônico ICP-Brasil.","Para que o e-mail tenha valor documental, basta que seja enviado do endereço eletrônico oficial; o destinatário não pode reconhecer como válido o e-mail sem certificação digital ICP-Brasil, ainda que não haja questionamento.","Manual, item 6.4.2.","dispensa ICP-Brasil e veda aceitação","item 6.4.2")
M(16,"troca_efeito",3,"Em e-mail oficial, o campo 'Assunto' deve ser claro e específico (como 'Agendamento de reunião sobre a Reforma da Previdência', e não 'Reunião'), e local e data são desnecessários no corpo da mensagem, pois o sistema apresenta essa informação.","Em e-mail oficial, o campo 'Assunto' deve ser genérico e curto (como 'Reunião') para não parecer lixo eletrônico, e local e data são obrigatórios no corpo da mensagem, como nos demais expedientes.","Manual, itens 6.4.3.1 e 6.4.3.2.","inverte regras de assunto e data","itens 6.4.3.1 e 6.4.3.2")
M(16,"excecao_omitida",3,"'Atenciosamente' é o fecho padrão das comunicações oficiais por e-mail; abreviações como 'Att.' e fechos como 'Abraços' e 'Saudações' são amplamente usados, mas não são fechos oficiais e não devem ser utilizados em e-mails profissionais.","'Att.' é a abreviação oficial do fecho 'Atenciosamente' no e-mail, e fechos como 'Abraços' e 'Saudações' são admitidos nas comunicações oficiais por correio eletrônico, desde que o destinatário seja de mesma hierarquia.","Manual, item 6.4.3.4.","admite fechos não oficiais","item 6.4.3.4")
M(16,"excecao_omitida",3,"O e-mail pode ser considerado documento oficial como gênero textual, devendo evitar linguagem incompatível com uma comunicação oficial, e, como endereço eletrônico de servidor, deve ser oficial, com a extensão '.gov.br', por exemplo.","O e-mail, por sua flexibilidade, não é considerado documento oficial como gênero textual, podendo adotar linguagem informal, e o endereço eletrônico do servidor pode ser particular, desde que identifique o cargo.","Manual, item 6.4.1.","nega caráter oficial","item 6.4.1")
# ---- siglas e acrônimos (átomo 17)
M(17,"confusao_instituto",3,"Para o Manual, sigla é o resultado da soma das iniciais de um título (Caixa Econômica Federal – CEF), ao passo que acrônimo é o resultado da soma de algumas sílabas ou partes dos vocábulos de um título (Agência Nacional de Vigilância Sanitária – Anvisa).","Para o Manual, acrônimo é o resultado da soma das iniciais de um título (Caixa Econômica Federal – CEF), ao passo que sigla é o resultado da soma de algumas sílabas ou partes dos vocábulos de um título (Agência Nacional de Vigilância Sanitária – Anvisa).","Manual, item 10.6.","inverte sigla e acrônimo","item 10.6")
M(17,"norma_culta",3,"Siglas de até três letras grafam-se em maiúsculas (ONU, OAB), e as de mais de três letras pronunciadas separadamente também (IBGE, INSS).","Siglas de até três letras grafam-se em maiúsculas (ONU, OAB), mas as de mais de três letras pronunciadas separadamente grafam-se apenas com a inicial maiúscula (Ibge, Inss).","Manual, item 10.6.","altera grafia de siglas soletradas","item 10.6")
M(17,"norma_culta",3,"Siglas de mais de três letras pronunciadas formando uma palavra são escritas apenas com a inicial maiúscula, como 'Anac'; já as de leitura mista, como DNIT e HRAN, podem ser grafadas com todas as letras maiúsculas.","Siglas de mais de três letras pronunciadas formando uma palavra são escritas com todas as letras maiúsculas, como 'ANAC'; já as de leitura mista, como DNIT e HRAN, exigem apenas a inicial maiúscula.","Manual, item 10.6.","inverte grafia de siglas","item 10.6")
M(17,"excecao_omitida",4,"Excepcionalmente, pode haver a concorrência de letras maiúsculas e minúsculas na estrutura da sigla, a fim de evitar confusão com outros termos assemelhados, como em 'CNPq'.","A mistura de letras maiúsculas e minúsculas não é admitida na estrutura da sigla, razão pela qual a sigla do Conselho Nacional de Desenvolvimento Científico e Tecnológico deve ser grafada 'CNPQ'.","Manual, item 10.6.","veda sigla mista","item 10.6")
M(17,"norma_culta",3,"No plural de siglas, admite-se o 's' minúsculo sem apóstrofo (TREs, e não TRE's), regra que não se aplica às siglas terminadas em 's' (como DVS), em que o plural é definido pelo artigo.","No plural de siglas, usa-se o 's' minúsculo com apóstrofo (TRE's) e, nas siglas terminadas em 's' (como DVS), acrescenta-se outro 's' (DVSs).","Manual, item 10.6.","altera plural de siglas","item 10.6")
M(17,"excecao_omitida",3,"Na primeira citação, a expressão designada vem por extenso, de forma completa e correta, antes da sigla, separados por travessão; dispensa-se o desdobramento apenas para partidos políticos e empresas comerciais cuja forma abreviada tenha virado sinônimo do nome, exceto empresas públicas ou estatais.","Na primeira citação, a sigla vem antes da expressão designada, separadas por travessão; dispensa-se o desdobramento para partidos políticos e empresas em geral, inclusive empresas públicas e estatais, cuja forma abreviada seja conhecida.","Manual, item 10.6.","inverte ordem e amplia dispensa","item 10.6")
M(17,"norma_culta",2,"As siglas e os acrônimos devem ser escritos no mesmo corpo do texto, sem o uso de pontos intermediários ou finais.","As siglas e os acrônimos devem ser escritos em corpo menor que o do texto e com pontos intermediários, como em 'S.T.F.'.","Manual, item 10.6.","exige pontos e corpo menor","item 10.6")
M(17,"restricao_indevida",4,"Em atos normativos, não se utiliza sigla para designar órgãos da administração pública direta nem atos normativos, e a sigla de entidade da administração indireta só é usada se prevista em lei.","Em atos normativos, recomenda-se utilizar sigla para designar órgãos da administração pública direta e atos normativos, a fim de abreviar o texto, e a sigla de entidade da administração indireta é livre.","Manual, item 10.6.1.","inverte vedações em atos normativos","item 10.6.1")
M(17,"excecao_omitida",4,"Devem-se empregar as siglas dos órgãos estrangeiros na versão em português (como Opep), adotando-se a forma abreviada original apenas quando o seu uso for disseminado internacionalmente.","Devem-se empregar as siglas dos órgãos estrangeiros na forma original, adotando-se a versão em português apenas quando o órgão tiver sede no Brasil.","Manual, item 10.6.","inverte regra de siglas estrangeiras","item 10.6")
M(17,"norma_culta",2,"Os símbolos de unidades de medida não levam ponto nem plural, como em '10 km' e '5 kg', ao passo que as abreviaturas terminam em ponto, como 'art.' e 'Sr.'.","Os símbolos de unidades de medida levam ponto e plural, como em '10 kms.' e '5 kgs.', ao passo que as abreviaturas não admitem ponto, como em 'art' e 'Sr'.","Convenção geral (Sistema Internacional); não consta do Manual.","aplica ponto e plural a símbolos","", True)
